import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { FiCamera, FiTrash2, FiUser } from "react-icons/fi";
import ProfilePictureModal from "./ProfilePictureModal";
import MyProfileModal from "./MyProfileModal";
import { useAuth } from "../../../auth/model/AuthContext";

export default function TrainerProfileMenu() {
  const { user, updateProfilePicture, removeProfilePicture } = useAuth();
  const [menuOpen, setMenuOpen] = useState(false);
  const [picModalOpen, setPicModalOpen] = useState(false);
  const [profileModalOpen, setProfileModalOpen] = useState(false);
  const menuRef = useRef(null);

  const profilePhoto = user?.profilePhotoUrl || user?.profilePicture;
  const initials = (user?.fullName || "Trainer").slice(0, 1).toUpperCase();

  useEffect(() => {
    function handleClickOutside(event) {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setMenuOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleRemovePicture = async () => {
    try {
      await removeProfilePicture();
      setMenuOpen(false);
    } catch (err) {
      // Error is handled in context/api, or we could add a toast here
    }
  };

  return (
    <div className="relative" ref={menuRef}>
      <button
        type="button"
        onClick={() => setMenuOpen(!menuOpen)}
        className="flex h-11 w-11 items-center justify-center overflow-hidden rounded-full border-2 border-[#006b58] bg-emerald-50 text-[#00342b] transition-transform hover:scale-105 active:scale-95"
        aria-label="Profile menu"
      >
        {profilePhoto ? (
          <img src={profilePhoto} alt="Profile" className="h-full w-full object-cover" />
        ) : (
          <span className="text-sm font-extrabold">{initials}</span>
        )}
      </button>

      <AnimatePresence>
        {menuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -10, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -10, scale: 0.95 }}
            transition={{ duration: 0.15 }}
            className="absolute right-0 mt-2 w-56 origin-top-right rounded-2xl border border-slate-200 bg-white p-2 shadow-xl z-50"
          >
            <div className="mb-2 border-b border-slate-100 px-3 pb-3 pt-2">
              <p className="truncate text-sm font-extrabold text-slate-900">{user?.fullName || "Trainer"}</p>
              <p className="truncate text-xs font-semibold text-slate-500">{user?.email}</p>
            </div>

            <div className="space-y-1">
              <button
                type="button"
                onClick={() => {
                  setProfileModalOpen(true);
                  setMenuOpen(false);
                }}
                className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-bold text-slate-700 transition-colors hover:bg-emerald-50 hover:text-[#006b58]"
              >
                <FiUser className="text-lg" />
                My Profile
              </button>

              <button
                type="button"
                onClick={() => {
                  setPicModalOpen(true);
                  setMenuOpen(false);
                }}
                className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-bold text-slate-700 transition-colors hover:bg-emerald-50 hover:text-[#006b58]"
              >
                <FiCamera className="text-lg" />
                Update Picture
              </button>

              {profilePhoto && (
                <button
                  type="button"
                  onClick={handleRemovePicture}
                  className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-bold text-red-600 transition-colors hover:bg-red-50"
                >
                  <FiTrash2 className="text-lg" />
                  Remove Picture
                </button>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <MyProfileModal 
        isOpen={profileModalOpen} 
        onClose={() => setProfileModalOpen(false)} 
      />

      <ProfilePictureModal
        isOpen={picModalOpen}
        onClose={() => setPicModalOpen(false)}
        onSave={async (newPicFile) => {
          await updateProfilePicture(newPicFile);
          setPicModalOpen(false);
        }}
        currentPicture={profilePhoto}
      />
    </div>
  );
}
